select id, metric_code, metric_date, dept_id, metric_value, unit, data_flag, snapshot_time
from bi_metric_snapshot
where metric_date = #{metricDate}

select id, metric_code, metric_date, dept_id, metric_value, unit, data_flag, snapshot_time
from bi_metric_snapshot
where
dept_id = 0

    dept_id in
    #{did}

  and metric_date >= #{startDate}
  and metric_date <= #{endDate}
order by metric_date, metric_code

select id, metric_code, metric_date, dept_id, metric_value, unit, data_flag, snapshot_time
from bi_metric_snapshot
where metric_code = #{metricCode} and metric_date = #{metricDate}
and dept_id = #{deptId}
and dept_id = 0
limit 1
